            pw.println("=== Application Classes Analyzed ===");
            pw.println();
            List<IClass> appClasses = new ArrayList<>();
            for (IClass klass : cha) {
                if (klass.getClassLoader().getReference().equals(ClassLoaderReference.Application)) {
                    appClasses.add(klass);
                }
            }
            appClasses.sort(Comparator.comparing(c -> c.getName().toString()));
            for (IClass klass : appClasses) {
                pw.println(klass.getName().toString() + " (" + klass.getDeclaredMethods().size() + " methods)");
            }
            pw.println();
            pw.println("Total application classes: " + appClasses.size());
        }

