/**
 * WALA analysis driver for the JMH (Java Microbenchmark Harness) project.
 * Performs:
 *  - Class hierarchy analysis
 *  - Call graph construction (0-1-CFA)
 *  - Pointer analysis
 *  - Collects and outputs statistics
 */
public class JmhAnalysisDriver {

    public static void main(String[] args) throws Exception {
        String appClassPath = args[0];
        String outputDir = args.length > 1 ? args[1] : "/analysis-results";
        String exclusionFile = args.length > 2 ? args[2] : null;

        System.out.println("=== WALA Analysis of JMH ===");
        System.out.println("Application classpath: " + appClassPath);
        System.out.println("Output directory: " + outputDir);

        long startTime = System.currentTimeMillis();

        // Step 1: Create analysis scope
        System.out.println("\n[1/5] Creating analysis scope...");
        AnalysisScope scope;
        if (exclusionFile != null) {
            scope = com.ibm.wala.core.util.config.AnalysisScopeReader.instance
                    .makeJavaBinaryAnalysisScope(appClassPath, new java.io.File(exclusionFile));
        } else {
            scope = com.ibm.wala.core.util.config.AnalysisScopeReader.instance
                    .makeJavaBinaryAnalysisScope(appClassPath, (java.io.File) null);
        }

        // Step 2: Build class hierarchy
        System.out.println("[2/5] Building class hierarchy...");
        ClassHierarchy cha = ClassHierarchyFactory.make(scope);
        int numClasses = cha.getNumberOfClasses();
        System.out.println("  Classes in hierarchy: " + numClasses);

        // Count application classes
        int appClassCount = 0;
        for (IClass klass : cha) {
            if (klass.getClassLoader().getReference().equals(ClassLoaderReference.Application)) {
                appClassCount++;
            }
        }
        System.out.println("  Application classes: " + appClassCount);

        // Step 3: Find entrypoints
        System.out.println("[3/5] Finding entrypoints...");
        Iterable<Entrypoint> entrypoints = Util.makeMainEntrypoints(cha);
        int entrypointCount = 0;
        for (Entrypoint e : entrypoints) {
            entrypointCount++;
        }
        System.out.println("  Entry points found: " + entrypointCount);

        // Step 4: Build call graph
        System.out.println("[4/5] Building call graph (0-1-CFA)...");
        AnalysisOptions options = new AnalysisOptions(scope, entrypoints);
        options.setReflectionOptions(com.ibm.wala.ipa.callgraph.AnalysisOptions.ReflectionOptions.NONE);
        IAnalysisCacheView cache = new AnalysisCacheImpl();
        CallGraphBuilder<InstanceKey> builder = Util.makeZeroOneContainerCFABuilder(options, cache, cha);
        CallGraph cg = builder.makeCallGraph(options, null);
        System.out.println("  Call graph built successfully.");

        // Step 5: Pointer analysis
        System.out.println("[5/5] Getting pointer analysis...");
        PointerAnalysis<InstanceKey> pa = builder.getPointerAnalysis();

        long endTime = System.currentTimeMillis();
        System.out.println("\n=== Analysis complete in " + (endTime - startTime) + "ms ===");

        // Generate output
        generateReport(cg, cha, pa, outputDir, appClassPath, numClasses, appClassCount, entrypointCount, endTime - startTime);
        System.out.println("\nResults written to " + outputDir);
    }

    private static void generateReport(CallGraph cg, ClassHierarchy cha, PointerAnalysis<InstanceKey> pa,
            String outputDir, String appClassPath, int numClasses, int appClassCount,
            int entrypointCount, long analysisTime) throws IOException {

        java.io.File outDir = new java.io.File(outputDir);
        outDir.mkdirs();

        // 1. Summary statistics file
        try (PrintWriter pw = new PrintWriter(new FileWriter(new java.io.File(outDir, "wala_jmh_analysis_summary.txt")))) {
            pw.println("=== WALA Analysis Summary for JMH ===");
            pw.println("Project: jmh (Java Microbenchmark Harness)");
            pw.println("Repository: https://github.com/openjdk/jmh");
            pw.println("Analysis Tool: WALA (https://github.com/wala/WALA)");
            pw.println("Date: " + new java.util.Date());
            pw.println();
            pw.println("=== Configuration ===");
            pw.println("Application classpath: " + appClassPath);
            pw.println("Call graph algorithm: 0-1-CFA (Zero-One Container CFA)");
            pw.println("Reflection handling: NONE");
            pw.println();
            pw.println("=== Analysis Statistics ===");
            pw.println("Total classes in hierarchy: " + numClasses);
            pw.println("Application classes: " + appClassCount);
            pw.println("Entry points: " + entrypointCount);
            pw.println();

            // Call graph stats
            int numNodes = cg.getNumberOfNodes();
            int numEdges = 0;
            Set<CGNode> appNodes = new HashSet<>();
            for (CGNode node : cg) {
                numEdges += cg.getSuccNodeCount(node);
                if (node.getMethod().getDeclaringClass().getClassLoader().getReference()
                        .equals(ClassLoaderReference.Application)) {
                    appNodes.add(node);
                }
            }
            pw.println("=== Call Graph Statistics ===");
            pw.println("Total CG nodes: " + numNodes);
            pw.println("Total CG edges: " + numEdges);
            pw.println("Application CG nodes: " + appNodes.size());
            pw.println();

            // Count app edges
            int appEdges = 0;
            for (CGNode node : appNodes) {
                for (CGNode succ : cg) {
                    if (cg.hasEdge(node, succ)) {
                        appEdges++;
                    }
                }
            }
            pw.println("Application CG edges: " + appEdges);
            pw.println();

            // Pointer analysis stats
            int numPointerKeys = 0;
            for (Object pk : pa.getPointerKeys()) {
                numPointerKeys++;
            }
            pw.println("=== Pointer Analysis Statistics ===");
            pw.println("Pointer keys: " + numPointerKeys);
            pw.println();

            pw.println("=== Analysis Time ===");
            pw.println("Total time: " + analysisTime + "ms");
            pw.println();

            // Class hierarchy stats
            pw.println("=== Class Hierarchy Details ===");
            int appMethods = 0;
            int totalMethods = 0;
            for (IClass klass : cha) {
                totalMethods += klass.getDeclaredMethods().size();
                if (klass.getClassLoader().getReference().equals(ClassLoaderReference.Application)) {
                    appMethods += klass.getDeclaredMethods().size();
                }
            }
            pw.println("Total methods: " + totalMethods);
            pw.println("Application methods: " + appMethods);
            pw.println();

            // Find classes with most methods (top 10 application classes)
            pw.println("=== Top 10 Application Classes by Method Count ===");
            List<IClass> appClasses = new ArrayList<>();
            for (IClass klass : cha) {
                if (klass.getClassLoader().getReference().equals(ClassLoaderReference.Application)) {
                    appClasses.add(klass);
                }
            }
            appClasses.sort((a, b) -> Integer.compare(
                    b.getDeclaredMethods().size(), a.getDeclaredMethods().size()));
            for (int i = 0; i < Math.min(10, appClasses.size()); i++) {
                IClass klass = appClasses.get(i);
                pw.println("  " + klass.getName().toString() + ": " + klass.getDeclaredMethods().size() + " methods");
            }
            pw.println();

            // Call graph stats from WALA
            pw.println("=== WALA CallGraphStats ===");
            pw.println(CallGraphStats.getStats(cg));
        }

        // 2. Call graph edges (application loader only) - DOT format
        try (PrintWriter pw = new PrintWriter(new FileWriter(new java.io.File(outDir, "wala_jmh_callgraph.dot")))) {
            pw.println("digraph JMH_CallGraph {");
            pw.println("  rankdir=LR;");
            pw.println("  node [shape=box, fontname=\"Helvetica\", fontsize=10];");
            pw.println("  edge [fontname=\"Helvetica\", fontsize=9];");

            Set<String> printedNodes = new HashSet<>();
            Set<CGNode> appNodeSet = new HashSet<>();
            for (CGNode node : cg) {
                if (node.getMethod().getDeclaringClass().getClassLoader().getReference()
                        .equals(ClassLoaderReference.Application)) {
                    appNodeSet.add(node);
                }
            }

            for (CGNode node : appNodeSet) {
                String nodeId = "n" + System.identityHashCode(node);
                if (!printedNodes.contains(nodeId)) {
                    printedNodes.add(nodeId);
                    String label = sanitizeDotLabel(node.getMethod().toString());
                    pw.println("  " + nodeId + " [label=\"" + label + "\"];");
                }
            }

            int edgeCount = 0;
            for (CGNode src : appNodeSet) {
                String srcId = "n" + System.identityHashCode(src);
                for (CGNode dst : cg) {
                    if (cg.hasEdge(src, dst) && appNodeSet.contains(dst)) {
                        String dstId = "n" + System.identityHashCode(dst);
                        pw.println("  " + srcId + " -> " + dstId + ";");
                        edgeCount++;
                        if (edgeCount > 5000) {
                            pw.println("  // ... truncated for readability ...");
                            break;
                        }
                    }
                }
                if (edgeCount > 5000) break;
            }
            pw.println("}");
        }

        // 3. List all application classes analyzed
        try (PrintWriter pw = new PrintWriter(new FileWriter(new java.io.File(outDir, "wala_jmh_classes.txt")))) {
            pw.println("=== Application Classes Analyzed ===");
            pw.println();
            List<IClass> appClasses = new ArrayList<>();
            for (IClass klass : cha) {
                if (klass.getClassLoader().getReference().equals(ClassLoaderReference.Application)) {
                    appClasses.add(klass);
                }
            }
            appClasses.sort(Comparator.comparing(c -> c.getName().toString()));
            for (IClass klass : appClasses) {
                pw.println(klass.getName().toString() + " (" + klass.getDeclaredMethods().size() + " methods)");
            }
            pw.println();
            pw.println("Total application classes: " + appClasses.size());
        }

        // 4. Call graph node listing (application loader)
        try (PrintWriter pw = new PrintWriter(new FileWriter(new java.io.File(outDir, "wala_jmh_callgraph_nodes.txt")))) {
            pw.println("=== Call Graph Nodes (Application Loader) ===");
            pw.println();
            Set<CGNode> appNodeSet = new HashSet<>();
            for (CGNode node : cg) {
                if (node.getMethod().getDeclaringClass().getClassLoader().getReference()
                        .equals(ClassLoaderReference.Application)) {
                    appNodeSet.add(node);
                }
            }
            List<CGNode> sortedNodes = new ArrayList<>(appNodeSet);
            sortedNodes.sort(Comparator.comparing(n -> n.getMethod().toString()));
            for (CGNode node : sortedNodes) {
                int outDegree = cg.getSuccNodeCount(node);
                pw.println(node.getMethod().toString() + " [out-degree=" + outDegree + "]");
            }
            pw.println();
            pw.println("Total application CG nodes: " + appNodeSet.size());
        }

        // 5. Reachable methods from entrypoints
        try (PrintWriter pw = new PrintWriter(new FileWriter(new java.io.File(outDir, "wala_jmh_reachable_methods.txt")))) {
            pw.println("=== Reachable Methods from Entry Points ===");
            pw.println();
            Set<CGNode> appNodes = new HashSet<>();
            for (CGNode node : cg) {
                if (node.getMethod().getDeclaringClass().getClassLoader().getReference()
                        .equals(ClassLoaderReference.Application)) {
                    appNodes.add(node);
                }
            }
            List<CGNode> sortedNodes = new ArrayList<>(appNodes);
            sortedNodes.sort(Comparator.comparing(n -> n.getMethod().getDeclaringClass().getName().toString()
                    + "#" + n.getMethod().getName().toString()));
            for (CGNode node : sortedNodes) {
                pw.println(node.getMethod().getDeclaringClass().getName().toString()
                        + "#" + node.getMethod().getName().toString()
                        + " " + node.getMethod().getDescriptor());
            }
            pw.println();
            pw.println("Total reachable application methods: " + appNodes.size());
        }

        System.out.println("\n=== Output Files ===");
        for (java.io.File f : outDir.listFiles()) {
            System.out.println("  " + f.getAbsolutePath() + " (" + f.length() + " bytes)");
        }
    }

    private static String sanitizeDotLabel(String s) {
        return s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", " ");
    }
}
